"""Session-only blinding guard. No study path is inspected to deny it."""
import builtins
import io
import os
import re
import sys

_ROOT = '/Users/edr/code/CapstoneProject/jw-wt/sol-prune-s5'
_OBJECTS = '/Users/edr/jw-b5-analysis/.git/objects'
_TMP = '/private/tmp/prune-s5-test-root'
_BLOCKED = []
_ANCESTORS = {'/Users/edr', '/Users/edr/code', '/Users/edr/code/CapstoneProject', '/Users/edr/code/CapstoneProject/jw-wt'}

def _denied(path):
    if isinstance(path, int) or path is None:
        return False
    path = os.fsdecode(path)
    # abspath/normpath are lexical; do not resolve a forbidden path.
    path = os.path.abspath(path)
    path = '/private' + path if path.startswith('/tmp/') else path
    if any(path.startswith(_ROOT + '/' + prefix) for prefix in ('tests/fixtures/d117_v2_production/', 'tests/fixtures/controller_g2b/', 'docs/process_traces/')):
        return True
    if 'restricted' in path.split('/') and not (path == _TMP or path.startswith(_TMP + '/')):
        return True
    return (path == '/Users/edr' or path.startswith('/Users/edr/')) and not (
        path == _ROOT or path.startswith(_ROOT + '/') or path.startswith(_OBJECTS + '/'))

def _check(path):
    if _denied(path):
        _BLOCKED.append(os.fsdecode(path))
        raise FileNotFoundError(2, 'outside blinded test workspace', os.fsdecode(path))

def _wrap(fn):
    def guarded(path, *args, **kwargs):
        if isinstance(path, (str, bytes, os.PathLike)) and os.fsdecode(path) in _ANCESTORS:
            # Virtual directory metadata, never a stat of the operator tree.
            if fn.__name__ in ('stat', 'lstat'):
                return os.stat_result((0o40755, 0, 0, 1, 0, 0, 0, 0, 0, 0))
            if fn.__name__ == 'readlink':
                raise OSError(22, 'virtual ancestor is not a symlink')
        _check(path)
        return fn(path, *args, **kwargs)
    return guarded

# stat has no Python audit event. Guard it before the OS sees the pathname.
for _name in ('stat', 'lstat', 'readlink', 'listdir', 'scandir'):
    setattr(os, _name, _wrap(getattr(os, _name)))

def _audit(event, args):
    if event == 'open' or event in ('os.listdir', 'os.scandir', 'os.chdir', 'os.mkdir', 'os.remove', 'os.rmdir', 'os.chmod', 'os.chflags', 'os.truncate'):
        _check(args[0])
    elif event in ('os.rename', 'os.link', 'os.symlink'):
        _check(args[0]); _check(args[1])
    elif event in ('socket.connect', 'socket.bind', 'socket.getaddrinfo'):
        raise PermissionError('network disabled for prune-s5 checks')
    elif event == 'subprocess.Popen':
        command = args[1]
        text = ' '.join(map(str, command)) if not isinstance(command, str) else command
        for match in re.finditer(r'/Users/edr[^\s\x00\"\'<>;]*', text):
            # Do not allow a child argv to name external operator state.
            _check(match.group())
        words = command if isinstance(command, (list, tuple)) else text.split()
        if any(str(word) in ('-I', '-E', '-S') for word in words):
            raise PermissionError('child disabled Python guard loading')
        if 'https://' in text or 'http://' in text or 'git@' in text:
            raise PermissionError('network URL disabled for prune-s5 checks')
        if any(os.path.basename(str(word)) in ('ssh', 'scp', 'curl', 'wget', 'sudo', 'powermetrics', 'launchctl', 'pmset') for word in words):
            raise PermissionError('network command disabled for prune-s5 checks')
        env = args[3]
        if env is not None and env.get('PRUNE_S5_GUARDED') != '1':
            raise PermissionError('child removed prune-s5 blinding guard')

sys.addaudithook(_audit)
# Metal is unavailable here. Make optional dependency probes and imports agree.
for _name in ('mlx', 'mlx.core', 'mlx_lm'):
    sys.modules[_name] = None
os.environ['PRUNE_S5_GUARDED'] = '1'
os.environ['PYTHONDONTWRITEBYTECODE'] = '1'
os.environ['JW_B5_SYNTHETIC_ONLY'] = '1'
os.environ['JOULEWISE_CUSTODY_PARENT'] = _TMP + '/custody'
os.environ['JOULEWISE_ADDITIONAL_CUSTODY_PARENTS'] = '[]'
os.environ['R7F_CORPUS_ROOT'] = _ROOT
os.environ['GIT_CONFIG_GLOBAL'] = '/dev/null'
os.environ['GIT_CONFIG_NOSYSTEM'] = '1'

sys.path.append(_ROOT + '/tests')

if '-m' in sys.orig_argv and 'unittest' in sys.orig_argv:
    with open('/private/tmp/prune-s5-owned-test.json', 'w') as _owner:
        import json as _json
        _json.dump(dict(runner_pid=os.getppid(), test_pid=os.getpid(), module=sys.orig_argv[-1]), _owner)
